#!/usr/bin/env python3
"""ختامُ صنف «كتب الفقه الإسلامي» في `qa_questions` من **كشاف القناع للبهوتي**.

الأربعةُ الباقية بعد ج-٢٣٨/ج-٢٣٩/ج-٢٤٠ لم تُفتح على المغني لعلّة اصطلاحيّة موثَّقة
(قاعدة ج-٢٣٨: امسح باب الكتاب بحثًا عن اللفظ قبل نسبة اصطلاح إليه): فالمغني على
مختصر الخِرَقي لا يستعمل «فرض كفاية» في الجنائز أصلًا، ولا يعقِد فصلًا لـ«أركان الحج»
ولا لـ«شروط الصلاة» مسرودةً معدودة. وكشافُ القناع — شرحُ البهوتي على متن الإقناع —
يسوق الثلاثة **بهذه الاصطلاحات نفسها معدودةً مبوَّبة**، فهو الكتاب الذي تُفتح عليه.

المنهج نفسه: تحديدُ الفصل، ثم **قراءةُ الصفحة**، ثم نقلُ نصّها **بحروفه وتشكيله**
(بأداة `mughni-lookup.py --book kashaf quote` بعد تعميمها في ج-٢٤١) إلى `evidence`
مع الجزء والصفحة المطبوعة، وتصحيحُ `answer` حيث خالف المنقول.

⚠️ الأقواس في الكشاف ليست حواشيَ محقِّق بل **متنُ الإقناع** يميَّز بها عن الشرح، فلا
يُعلَّم الكتاب بـ`parenfn` (خلافًا لقاعدة ج-٢٣٩) — والتحقّق: ٠ كتلة `hamesh` و٠ علامة
إحالة في الصفحات الممسوحة. ولذلك تَرِد الأقواس في المقتبسات كما هي في المطبوع.

كلُّ `UPDATE` مقيَّدٌ بـ`id` وبنصّ `reference` و`evidence` و`answer` الأصلية ⇒
idempotent، ولا يُصيب صفًّا تغيَّر بعد توليد الملفّ.
"""
import json
import os
import sys

OUT = os.path.join(os.path.dirname(os.path.abspath(__file__)),
                   "..", "supabase", "qa_questions_fiqh_kashaf_verify.sql")

BOOK = "كشاف القناع عن متن الإقناع للبهوتي، راجعه هلال مصيلحي (٦ أجزاء)"

# (المعرِّف، الموضع، نصّ `evidence` الجديد، نصّ `answer` الجديد أو None)
